ControlPropertyState.AutoRuleBindingString:
If(
    varPHR_Page < RoundUp(varPHR_TotalCount / varPHR_PageSize, 0),
    Set(varPHR_Page, varPHR_Page + 1);
    Select(btnPHR_Search)
)

// ======================================================
// PHR - Rebuild active L1 tab
// Rebuilds grouped headers and visible matrix cells
// ======================================================

// 1) Ensure selected L1 exists
If(
    IsBlank(varPHR_SelectedL1NodeId) && CountRows(colPHR_HeaderL1Base) > 0,
    Set(varPHR_SelectedL1NodeId, First(colPHR_HeaderL1Base).L1NodeId);
    Set(varPHR_SelectedL1Label, First(colPHR_HeaderL1Base).L1Label)
);

// 2) Build active L4 columns for selected L1
ClearCollect(
    colPHR_HeaderL4_Active,
    AddColumns(
        SortByColumns(
            Filter(
                colPHR_HeaderL4Indexed,
                Text(L1NodeId) = Text(varPHR_SelectedL1NodeId)
            ),
            "ColIndex",
            SortOrder.Ascending
        ),
        LocalColIndex,
        CountRows(
            Filter(
                colPHR_HeaderL4Indexed,
                Text(L1NodeId) = Text(varPHR_SelectedL1NodeId) &&
                ColIndex <= ThisRecord.ColIndex
            )
        )
    )
);

// 3) Build active L3 groups ordered by real horizontal position
ClearCollect(
    colPHR_HeaderL3_Active,
    SortByColumns(
        AddColumns(
            GroupBy(
                colPHR_HeaderL4_Active,
                L1NodeId,
                L1Label,
                L1SortOrder,
                L2NodeId,
                L2Label,
                L2SortOrder,
                L3NodeId,
                L3Label,
                L3SortOrder,
                Rows
            ),
            StartCol,
            Min(Rows, LocalColIndex),
            EndCol,
            Max(Rows, LocalColIndex),
            ColCount,
            CountRows(Rows),
            StartX,
            (Min(Rows, LocalColIndex) - 1) * varPHR_ColW,
            WidthPx,
            CountRows(Rows) * varPHR_ColW
        ),
        "StartCol",
        SortOrder.Ascending
    )
);

// 4) Build active L2 groups ordered by real horizontal position
ClearCollect(
    colPHR_HeaderL2_Active,
    SortByColumns(
        AddColumns(
            GroupBy(
                colPHR_HeaderL4_Active,
                L1NodeId,
                L1Label,
                L1SortOrder,
                L2NodeId,
                L2Label,
                L2SortOrder,
                Rows
            ),
            StartCol,
            Min(Rows, LocalColIndex),
            EndCol,
            Max(Rows, LocalColIndex),
            ColCount,
            CountRows(Rows),
            StartX,
            (Min(Rows, LocalColIndex) - 1) * varPHR_ColW,
            WidthPx,
            CountRows(Rows) * varPHR_ColW
        ),
        "StartCol",
        SortOrder.Ascending
    )
);

// 5) Build active L1 group ordered by real horizontal position
ClearCollect(
    colPHR_HeaderL1_Active,
    SortByColumns(
        AddColumns(
            GroupBy(
                colPHR_HeaderL4_Active,
                L1NodeId,
                L1Label,
                L1SortOrder,
                Rows
            ),
            StartCol,
            Min(Rows, LocalColIndex),
            EndCol,
            Max(Rows, LocalColIndex),
            ColCount,
            CountRows(Rows),
            StartX,
            0,
            WidthPx,
            CountRows(Rows) * varPHR_ColW
        ),
        "StartCol",
        SortOrder.Ascending
    )
);

// 6) Build active row cells
Clear(colPHR_RowCells_Active);

ForAll(
    colPHR_Subsystems As s,
    Collect(
        colPHR_RowCells_Active,
        AddColumns(
            colPHR_HeaderL4_Active As h,
            SubsystemCode,
            s.SubsystemCode,
            RowNo,
            s.RowNo,
            CellValue,
            Coalesce(
                LookUp(
                    colPHR_Metrics,
                    Text(SubsystemCode) = Text(s.SubsystemCode) &&
                    Text(MetricKey) = Text(h.MetricKey),
                    MetricValue
                ),
                0
            )
        )
    )
);

// 7) Recalculate active widths
Set(
    varPHR_DataColsWidth_Active,
    Max(
        CountRows(colPHR_HeaderL4_Active) * varPHR_ColW,
        varPHR_ColW
    )
);

Set(
    varPHR_TotalGridWidth_Active,
    varPHR_StatusW + varPHR_SubsysW + varPHR_ActionsW + varPHR_DataColsWidth_Active
);

// 8) Reset horizontal scroll
Reset(sldPHR_HOffset);

With(
    {
        _key: Lower(Trim(cmp_NavApp_Overview.SelectedItemKey)),
        _hasProject: !IsBlank(varProjectId)
    },
    If(
        _key <> "home" && !_hasProject,

        Notify("Please select a project first.", NotificationType.Warning);
        Set(varAppView, "Home");
        Navigate(scr_App, ScreenTransition.None),

        Switch(
            _key,

            "home",
                Set(varAppView, "Home");
                Navigate(scr_App, ScreenTransition.None),

            "overview",
                Set(varAppView, "Overview");
                Set(varOps_ViewMode, "OVERVIEW");
                Navigate(scr_Overview, ScreenTransition.None),

            "tasks",
                Set(varAppView, "Tasks");
                Navigate(scr_Tasks, ScreenTransition.None),

            "punches",
                Set(varAppView, "Punches");
                Navigate(scr_Punches, ScreenTransition.None),

            "briefing",
                Set(varAppView, "Briefing");
                Navigate(scr_Briefing, ScreenTransition.None),

            "config",
                Set(varAppView, "Config");
                Navigate(scr_Config, ScreenTransition.None),

            "superadmin",
                Set(varAppView, "SuperAdmin");
                Navigate(scr_SuperAdmin, ScreenTransition.None),

            Notify("Key not mapped: [" & _key & "]", NotificationType.Error)
        )
    )
)

Set(varTasks_ReturnView, "Overview");

Clear(colTasks);
Set(varTasks_Filter_Subsystem, ThisItem.SubsystemCode);
Set(varOps_ToTasks_L3NodeId, "");
Set(varOps_ToTasks_L3DisplayName, "");
Set(varTasks_ContextSource, "Home");


Set(varAppView, "Tasks");
Set(varApplySubsystemDefault, true);
Set(varTasks_Page, 1);

Select(btnTasks_LoadPage);

Set(varTasks_ReturnView, "Overview");

Set(varFilter_Subsystem, ThisItem.SubsystemCode);
Set(varAppView, "Punches");
Clear(colPunches);
Select(btnPunchApplyFilters);

Set(varTasksLoaded, false);
Set(varPage, 1);

With(
    {
        maxRemaining:
            Max(
                Filter(
                    colPHR_RowCells_Active,
                    Text(SubsystemCode) = Text(ThisItem.SubsystemCode) &&
                    Upper(Text(MetricLabel)) in ["REM.", "REMAINING"]
                ),
                Value(CellValue)
            )
    },
    If(
        maxRemaining >= 20,
        "Attention required · " & Text(maxRemaining) & " remaining",
        If(
            maxRemaining > 0,
            "In progress · " & Text(maxRemaining) & " remaining",
            "Ready · no remaining items"
        )
    )
)

With(
    {
        maxRemaining:
            Max(
                Filter(
                    colPHR_RowCells_Active,
                    Text(SubsystemCode) = Text(ThisItem.SubsystemCode) &&
                    Upper(Text(MetricLabel)) in ["REM.", "REMAINING"]
                ),
                Value(CellValue)
            )
    },
    If(
        maxRemaining >= 20,
        ColorValue("#DC2626"),
        If(
            maxRemaining > 0,
            ColorValue("#D97706"),
            ColorValue("#16A34A")
        )
    )
)

Set(varPHR_StartTabTimer, false);

Set(varPHR_SelectedL1NodeId, varPHR_PendingL1NodeId);
Set(varPHR_SelectedL1Label, varPHR_PendingL1Label);

Select(btnPHR_RebuildActiveTab);

Set(varPHR_TabSwitching, false);
Set(varPHR_TabSwitchMsg, "")
